import { useCallback, useEffect, useRef, useState } from 'react'
import type { AdminMachine } from '../../../../shared/admin'

const PAGE_SIZE = 50
const time = (value: number): string => new Date(value).toLocaleString('zh-CN', { hour12: false, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })

/** Machines seen in release-note read records. Anonymous: a machine ID is a random UUID generated by the client. */
export default function AdminMachines() {
  const alive = useRef(true)
  const request = useRef(0)
  const [queryDraft, setQueryDraft] = useState('')
  const [query, setQuery] = useState('')
  const [offset, setOffset] = useState(0)
  const [items, setItems] = useState<AdminMachine[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [blocked, setBlocked] = useState('')

  const queryInvalid = !/^[0-9a-fA-F-]*$/.test(queryDraft.trim())

  const load = useCallback(async (): Promise<void> => {
    const revision = ++request.current
    setLoading(true); setError('')
    try {
      const result = await window.api.listAdminMachines({ q: query, limit: PAGE_SIZE, offset })
      if (!alive.current || revision !== request.current) return
      if (!result.ok) { if (result.loginRequired || result.forbidden) setBlocked(result.message); else setError(result.message); return }
      setBlocked(''); setItems(result.value.items); setTotal(result.value.total)
    } catch { if (alive.current && revision === request.current) setError('读取机器列表失败，请重试。') }
    finally { if (alive.current && revision === request.current) setLoading(false) }
  }, [query, offset])

  useEffect(() => () => { alive.current = false }, [])
  useEffect(() => { void load() }, [load])
  useEffect(() => {
    const timer = window.setTimeout(() => {
      const next = queryDraft.trim().toLowerCase()
      if (!queryInvalid && next !== query) { setOffset(0); setQuery(next) }
    }, 350)
    return () => window.clearTimeout(timer)
  }, [queryDraft, query, queryInvalid])

  if (blocked) {
    return <section className="admin-page admin-page--blocked" role="alert">
      <h1>无法读取机器</h1><p>{blocked}</p>
      <button type="button" className="admin-btn" onClick={() => { setBlocked(''); void load() }}>重试</button>
    </section>
  }

  const to = offset + items.length
  return <section className="admin-page admin-machines">
    <header className="admin-page__header">
      <div><h1>机器</h1><p className="admin-muted">来自更新说明的已读记录：只包含打开过“版本更新说明”的客户端，机器 ID 是客户端本地生成的随机标识，不关联账号。</p></div>
      <button type="button" className="admin-btn" disabled={loading} onClick={() => void load()}>{loading ? '加载中…' : '刷新'}</button>
    </header>
    <div className="admin-toolbar">
      <span className="admin-muted">共 {total.toLocaleString('zh-CN')} 台</span>
      <div className="admin-filters">
        <input type="search" aria-label="搜索机器 ID" placeholder="搜索机器 ID" maxLength={36} value={queryDraft}
          aria-invalid={queryInvalid || undefined} onChange={event => setQueryDraft(event.target.value)} />
      </div>
    </div>
    {queryInvalid ? <p className="admin-error" role="alert">机器 ID 只包含十六进制字符和连字符。</p> : null}
    {error ? <div className="admin-error" role="alert">{error}<button type="button" className="admin-btn admin-btn--small" onClick={() => void load()}>重试</button></div> : null}
    <div className="admin-table-wrap" aria-busy={loading}>
      <table className="admin-table">
        <thead><tr><th>机器 ID</th><th>首次阅读</th><th>最近阅读</th><th className="is-number">已读版本</th><th className="is-number">反馈</th></tr></thead>
        <tbody>{items.map(item => <tr key={item.machineId}>
          <td className="admin-mono">{item.machineId}</td><td>{time(item.firstReadAt)}</td><td>{time(item.lastReadAt)}</td>
          <td className="is-number">{item.readCount}</td><td className="is-number">{item.feedbackCount || '—'}</td>
        </tr>)}</tbody>
      </table>
      {!items.length && !error ? <p className="admin-empty" role="status">{loading ? '正在加载…' : '没有机器记录'}</p> : null}
    </div>
    {total > PAGE_SIZE ? <div className="admin-pager admin-pager--flat">
      <span>第 {total ? offset + 1 : 0}–{to} 条，共 {total} 条</span>
      <button type="button" className="admin-btn admin-btn--small" disabled={loading || offset === 0} onClick={() => setOffset(Math.max(0, offset - PAGE_SIZE))}>上一页</button>
      <button type="button" className="admin-btn admin-btn--small" disabled={loading || to >= total} onClick={() => setOffset(offset + PAGE_SIZE)}>下一页</button>
    </div> : null}
  </section>
}
